-- Міграція адмінподілу в records під новий довідник (public/data/region_structure.json).
-- Згенеровано scripts/build-region-migration.mjs зі старого довідника 59e0c4b.
-- НЕ редагувати вручну — перегенерувати скриптом.
--
-- Порядок важливий: спершу правки назв (вони ключуються за СТАРОЮ трійкою),
-- потім самі трійки, потім «розхідні» (Українські етнічні землі).

-- === 0. Схема ================================================================
-- Країна потрібна в усіх трьох таблицях: форма пише в records_unverified,
-- звідки запис переїжджає в records при підтвердженні.

ALTER TABLE records            ADD COLUMN IF NOT EXISTS current_country text;
ALTER TABLE records_unverified ADD COLUMN IF NOT EXISTS current_country text;
ALTER TABLE records_edit       ADD COLUMN IF NOT EXISTS current_country text;

-- === 1. Прив'язки по коду ====================================================
-- 56 кодів зникли з довідника, 8 дісталися іншому пункту.
-- Ключі та підписки тримаються за код, тож перед міграцією варто переконатися,
-- що вони цього не зачепили. Обидва запити мають повернути порожньо.

SELECT id, name, center->>'code' AS code, 'center' AS where_
FROM map_keys WHERE center->>'code' IN ('BR10000000000000008', 'BS10000000000000021', 'ZK10000000000000007', 'ZK10000000000000008', 'ZK10000000000000009', 'ZK10000001000000021', 'ZK10000010000000026', 'ZK1000010000000030', 'ZK10000000000000036', 'ZK20000000000000001', 'ZK20000000000000003', 'ZK20000000000000005', 'ZK20000000000000006', 'ZK30000000000000061', 'ZK30000000000000091', 'ZK30000000000000092', 'ZK30000000000000105', 'ZK30000000000000106', 'ZK30000000000000107', 'ZK30000000000000108', 'ZK30000000000000109', 'ZK30000000000000110', 'ZK30000000000000112', 'ZK30000000000000113', 'ZK30000000000000114', 'ZK30000000000000115', 'ZK30000000000000121', 'ZK30000000000000125', 'ZK30000000000000126', 'ZK30000000000000127', 'ZK30000000000000128', 'ZK30000000000000129', 'ZK30000000000000130', 'ZK30000000000000131', 'ZK30000000000000133', 'ZK30000000000000134', 'ZK30000000000000135', 'ZK30000000000000147', 'ZK30000000000000148', 'ZK30000000000000149', 'ZK30000000000000150', 'ZK30000000000000151', 'ZK30000000000000152', 'ZK30000000000000153', 'ZK30000000000000154', 'ZK30000000000000155', 'SG00000000000000123', 'ZK40000000000000008', 'ZK40000000000000056', 'ZK40000000000000057', 'ZK40000000000000058', 'ZK40000000000000059', 'ZK40000000000000060', 'ZK40000000000000066', 'SG11000000000000132', 'SG11000000000000153', 'SG00000000000000125', 'SG00000000000000135', 'SG00000000000000136', 'SG00000000000000137', 'SG00000000000000138', 'SG00000000000000139', 'SG00000000000000140', 'SG00000000000000141')
UNION ALL
SELECT k.id, k.name, p->>'code', 'points'
FROM map_keys k, jsonb_array_elements(k.points) p
WHERE p->>'code' IN ('BR10000000000000008', 'BS10000000000000021', 'ZK10000000000000007', 'ZK10000000000000008', 'ZK10000000000000009', 'ZK10000001000000021', 'ZK10000010000000026', 'ZK1000010000000030', 'ZK10000000000000036', 'ZK20000000000000001', 'ZK20000000000000003', 'ZK20000000000000005', 'ZK20000000000000006', 'ZK30000000000000061', 'ZK30000000000000091', 'ZK30000000000000092', 'ZK30000000000000105', 'ZK30000000000000106', 'ZK30000000000000107', 'ZK30000000000000108', 'ZK30000000000000109', 'ZK30000000000000110', 'ZK30000000000000112', 'ZK30000000000000113', 'ZK30000000000000114', 'ZK30000000000000115', 'ZK30000000000000121', 'ZK30000000000000125', 'ZK30000000000000126', 'ZK30000000000000127', 'ZK30000000000000128', 'ZK30000000000000129', 'ZK30000000000000130', 'ZK30000000000000131', 'ZK30000000000000133', 'ZK30000000000000134', 'ZK30000000000000135', 'ZK30000000000000147', 'ZK30000000000000148', 'ZK30000000000000149', 'ZK30000000000000150', 'ZK30000000000000151', 'ZK30000000000000152', 'ZK30000000000000153', 'ZK30000000000000154', 'ZK30000000000000155', 'SG00000000000000123', 'ZK40000000000000008', 'ZK40000000000000056', 'ZK40000000000000057', 'ZK40000000000000058', 'ZK40000000000000059', 'ZK40000000000000060', 'ZK40000000000000066', 'SG11000000000000132', 'SG11000000000000153', 'SG00000000000000125', 'SG00000000000000135', 'SG00000000000000136', 'SG00000000000000137', 'SG00000000000000138', 'SG00000000000000139', 'SG00000000000000140', 'SG00000000000000141');

SELECT id, settlement_code, status
FROM settlement_subscription
WHERE settlement_code IN ('BR10000000000000008', 'BS10000000000000021', 'ZK10000000000000007', 'ZK10000000000000008', 'ZK10000000000000009', 'ZK10000001000000021', 'ZK10000010000000026', 'ZK1000010000000030', 'ZK10000000000000036', 'ZK20000000000000001', 'ZK20000000000000003', 'ZK20000000000000005', 'ZK20000000000000006', 'ZK30000000000000061', 'ZK30000000000000091', 'ZK30000000000000092', 'ZK30000000000000105', 'ZK30000000000000106', 'ZK30000000000000107', 'ZK30000000000000108', 'ZK30000000000000109', 'ZK30000000000000110', 'ZK30000000000000112', 'ZK30000000000000113', 'ZK30000000000000114', 'ZK30000000000000115', 'ZK30000000000000121', 'ZK30000000000000125', 'ZK30000000000000126', 'ZK30000000000000127', 'ZK30000000000000128', 'ZK30000000000000129', 'ZK30000000000000130', 'ZK30000000000000131', 'ZK30000000000000133', 'ZK30000000000000134', 'ZK30000000000000135', 'ZK30000000000000147', 'ZK30000000000000148', 'ZK30000000000000149', 'ZK30000000000000150', 'ZK30000000000000151', 'ZK30000000000000152', 'ZK30000000000000153', 'ZK30000000000000154', 'ZK30000000000000155', 'SG00000000000000123', 'ZK40000000000000008', 'ZK40000000000000056', 'ZK40000000000000057', 'ZK40000000000000058', 'ZK40000000000000059', 'ZK40000000000000060', 'ZK40000000000000066', 'SG11000000000000132', 'SG11000000000000153', 'SG00000000000000125', 'SG00000000000000135', 'SG00000000000000136', 'SG00000000000000137', 'SG00000000000000138', 'SG00000000000000139', 'SG00000000000000140', 'SG00000000000000141');

-- === 2. Значення адмінподілу =================================================

BEGIN;

CREATE TEMP TABLE region_map (
    old_region text, old_district text, old_community text,
    country text, region text, district text, community text
) ON COMMIT DROP;


CREATE TEMP TABLE settlement_map (
    old_region text, old_district text, old_community text, old_type text, old_name text,
    country text, region text, district text, community text, name text, type text
) ON COMMIT DROP;


CREATE TEMP TABLE name_fix (
    old_region text, old_district text, old_community text, old_type text, old_name text,
    name text, type text
) ON COMMIT DROP;


CREATE TEMP TABLE manual_map (
    old_region text, old_district text, old_type text, old_name text,
    country text, region text, district text, community text, name text, type text
) ON COMMIT DROP;


-- Обмеження з sql/2026-07-23_case_signature_consistency.sql додані як NOT VALID:
-- наявні рядки вони не перевіряли, але блокують будь-який UPDATE по них — і по
-- наших теж. Знімаємо на час міграції й повертаємо нижче точно такими самими,
-- теж NOT VALID. Семантика не змінюється: для нових записів вони діють як діяли.

ALTER TABLE records DROP CONSTRAINT IF EXISTS records_foreign_archive_has_no_parts;
ALTER TABLE records DROP CONSTRAINT IF EXISTS records_signature_matches_parts;

-- 0. Скільки записів зачепить (виконати й запамʼятати числа)
SELECT 'по трійці' AS through, count(*) FROM records r JOIN region_map m
    ON r.current_region = m.old_region AND r.current_district = m.old_district
   AND r.current_community = m.old_community
UNION ALL
SELECT 'по пункту', count(*) FROM records r JOIN settlement_map m
    ON r.current_region = m.old_region AND r.current_district = m.old_district
   AND r.current_community = m.old_community AND r.current_settlement_type = m.old_type
   AND r.current_settlement_name = m.old_name;

-- Порівнюємо назви з точністю до апострофа: у записах трапляються ' ` ʼ ´,
-- у довіднику всюди ’. Через це інакше не збігається, напр. «Кам`янка-Бузька».

-- 1. Перейменовані пункти й виправлені типи всередині незмінних трійок
UPDATE records r
SET current_settlement_name = f.name, current_settlement_type = f.type
FROM name_fix f
WHERE translate(r.current_region, '''`ʼ´', '’’’’') = translate(f.old_region, '''`ʼ´', '’’’’')
  AND translate(r.current_district, '''`ʼ´', '’’’’') = translate(f.old_district, '''`ʼ´', '’’’’')
  AND translate(r.current_community, '''`ʼ´', '’’’’') = translate(f.old_community, '''`ʼ´', '’’’’')
  AND r.current_settlement_type = f.old_type
  AND translate(r.current_settlement_name, '''`ʼ´', '’’’’') = translate(f.old_name, '''`ʼ´', '’’’’');

-- 2. Основна маса: трійка → країна + нові назви рівнів
UPDATE records r
SET current_country = m.country, current_region = m.region,
    current_district = m.district, current_community = m.community
FROM region_map m
WHERE translate(r.current_region, '''`ʼ´', '’’’’') = translate(m.old_region, '''`ʼ´', '’’’’')
  AND translate(r.current_district, '''`ʼ´', '’’’’') = translate(m.old_district, '''`ʼ´', '’’’’')
  AND translate(r.current_community, '''`ʼ´', '’’’’') = translate(m.old_community, '''`ʼ´', '’’’’');

-- 3. «Українські етнічні землі» — призначення залежить від самого пункту
UPDATE records r
SET current_country = m.country, current_region = m.region,
    current_district = m.district, current_community = m.community,
    current_settlement_name = m.name, current_settlement_type = m.type
FROM settlement_map m
WHERE translate(r.current_region, '''`ʼ´', '’’’’') = translate(m.old_region, '''`ʼ´', '’’’’')
  AND translate(r.current_district, '''`ʼ´', '’’’’') = translate(m.old_district, '''`ʼ´', '’’’’')
  AND translate(r.current_community, '''`ʼ´', '’’’’') = translate(m.old_community, '''`ʼ´', '’’’’')
  AND r.current_settlement_type = m.old_type
  AND translate(r.current_settlement_name, '''`ʼ´', '’’’’') = translate(m.old_name, '''`ʼ´', '’’’’');

-- 3a. Резерв для записів, де громада порожня або застаріла («Холмська земля»,
--     «Любачівщина»): зіставляємо без громади — за областю, районом, типом і
--     назвою. Беремо лише ті пари, що ведуть рівно в один новий вузол; решта
--     лишається на ручний розбір.
UPDATE records r
SET current_country = f.country, current_region = f.region,
    current_district = f.district, current_community = f.community,
    current_settlement_name = f.name, current_settlement_type = f.type
FROM (
    SELECT old_region, old_district, old_type, old_name,
           min(country) AS country, min(region) AS region, min(district) AS district,
           min(community) AS community, min(name) AS name, min(type) AS type
    FROM settlement_map
    GROUP BY old_region, old_district, old_type, old_name
    HAVING count(DISTINCT country || '|' || region || '|' || district || '|' || community) = 1
) f
WHERE r.current_country IS NULL
  AND translate(r.current_region, '''`ʼ´', '’’’’') = translate(f.old_region, '''`ʼ´', '’’’’')
  AND translate(r.current_district, '''`ʼ´', '’’’’') = translate(f.old_district, '''`ʼ´', '’’’’')
  AND r.current_settlement_type = f.old_type
  AND translate(r.current_settlement_name, '''`ʼ´', '’’’’') = translate(f.old_name, '''`ʼ´', '’’’’');

-- 3b. Ручні відповідності: пункти, зведені як дублі, з перевиданим кодом або
--     записані коротшою назвою («Перевали» → «Перевалля»). Ключ — область,
--     район, тип і назва; громаду не звіряємо з тієї самої причини, що в 3a.
UPDATE records r
SET current_country = m.country, current_region = m.region,
    current_district = m.district, current_community = m.community,
    current_settlement_name = m.name, current_settlement_type = m.type
FROM manual_map m
WHERE r.current_country IS NULL
  AND translate(r.current_region, '''`ʼ´', '’’’’') = translate(m.old_region, '''`ʼ´', '’’’’')
  AND translate(r.current_district, '''`ʼ´', '’’’’') = translate(m.old_district, '''`ʼ´', '’’’’')
  AND r.current_settlement_type = m.old_type
  AND translate(r.current_settlement_name, '''`ʼ´', '’’’’') = translate(m.old_name, '''`ʼ´', '’’’’');

-- 4. Повертаємо обмеження в тому вигляді, в якому вони були
ALTER TABLE records
  ADD CONSTRAINT records_signature_matches_parts CHECK (
    btrim(coalesce(archive, '')) = ''
    or btrim(coalesce(fonds,  '')) = ''
    or btrim(coalesce(series, '')) = ''
    or btrim(coalesce(record, '')) = ''
    or btrim(coalesce(case_signature, '')) =
       btrim(archive) || ' ' || btrim(fonds) || '-' || btrim(series) || '-' || btrim(record)
  ) NOT VALID;

ALTER TABLE records
  ADD CONSTRAINT records_foreign_archive_has_no_parts CHECK (
    is_ukrainian_archive is distinct from 'Ні'
    or (btrim(coalesce(archive, '')) = ''
        and btrim(coalesce(fonds,  '')) = ''
        and btrim(coalesce(series, '')) = ''
        and btrim(coalesce(record, '')) = '')
  ) NOT VALID;

-- 5. Що НЕ змапилося — на ручний розбір (має лишитися порожнім або містити
--    лише записи, введені вручну через manualEntry)
SELECT id, current_region, current_district, current_community,
       current_settlement_type, current_settlement_name
FROM records
WHERE current_country IS NULL
  AND coalesce(current_region, '') <> '';

COMMIT;
